   713	        case UI_WIDGET_EMPTY_STATE:
   714	            return ui_widget_paint_empty_state(canvas, spec);
   715	        case UI_WIDGET_INLINE_ERROR:
   716	        case UI_WIDGET_TOAST: {
   717	            if (spec->kind == UI_WIDGET_TOAST) draw_shadow(canvas, spec->bounds);
   718	            uint32_t surface = spec->state == UI_CONTROL_DISABLED ? canvas->tokens.panel_raised :
   719	                canvas->tokens.panel;
   720	            uint32_t tone_color = spec->tone == UI_WIDGET_TONE_SUCCESS ? canvas->tokens.success :
   721	                spec->tone == UI_WIDGET_TONE_WARNING ? canvas->tokens.warning :
   722	                spec->tone == UI_WIDGET_TONE_NEUTRAL ? canvas->tokens.accent : canvas->tokens.error;
   723	            if (spec->kind == UI_WIDGET_INLINE_ERROR && spec->tone == UI_WIDGET_TONE_NEUTRAL)
   724	                tone_color = canvas->tokens.error;
   725	            ui_widget_paint_round(canvas, spec->bounds, 6U, surface, tone_color, 1U);
   726	            if (!ui_widget_paint_icon(canvas, UI_ICON_CLOSE,
   727	                    (ui_rect){spec->bounds.x + 8U, spec->bounds.y + 8U, 14U, 14U},
   728	                    spec->kind == UI_WIDGET_TOAST ? UI_CONTROL_REST : UI_CONTROL_INVALID)) return false;
   729	            ui_rect label = {spec->bounds.x + 28U, spec->bounds.y + 1U,
   730	                spec->bounds.width > 36U ? spec->bounds.width - 36U : 0U, 17U};
   731	            ui_rect detail = {label.x, spec->bounds.y + 18U, label.width, 17U};
   732	            return ui_widget_paint_text(canvas, spec->label, spec->label_length, label,
   733	                    tone_color, UI_FONT_SYSTEM, UI_FONT_SEMIBOLD, 11U) &&
   734	                ui_widget_paint_text(canvas, spec->secondary, spec->secondary_length,
   735	                    detail, canvas->tokens.text_secondary, UI_FONT_SYSTEM,
   736	                    UI_FONT_REGULAR, 10U);
   737	        }
   738	        case UI_WIDGET_NUMBER_FIELD:
   739	        case UI_WIDGET_SCRUB_LABEL:
   740	        case UI_WIDGET_STEPPER:
   741	        case UI_WIDGET_COLOR_FIELD:
   742	        case UI_WIDGET_SLIDER:
   743	        case UI_WIDGET_DROPDOWN:
   744	        case UI_WIDGET_TEXT_FIELD:
   745	            return draw_input(canvas, spec);
   746	        case UI_WIDGET_KIND_COUNT: return false;
   747	    }
   748	    return false;
   749	}
   750	
   751	bool ui_widget_paint(ui_widget_canvas *canvas, const ui_widget_draw_spec *spec)
   752	{
   753	    if (!canvas_valid(canvas) || spec == NULL || spec->kind < UI_WIDGET_LABEL ||
   754	        spec->kind >= UI_WIDGET_KIND_COUNT || spec->state < UI_CONTROL_REST ||
   755	        spec->state > UI_CONTROL_INVALID || spec->bounds.width == 0U ||
   756	        spec->bounds.height == 0U || spec->bounds.width > UI_WIDGET_MAX_CANVAS_AXIS ||
   757	        spec->bounds.height > UI_WIDGET_MAX_CANVAS_AXIS ||
   758	        spec->label_length > UI_TEXT_TOTAL_MAX_BYTES ||
   759	        spec->value_length > UI_TEXT_TOTAL_MAX_BYTES ||
   760	        spec->secondary_length > UI_TEXT_TOTAL_MAX_BYTES ||
   761	        spec->unit_length > UI_WIDGET_UNIT_MAX_BYTES ||
   762	        spec->tone < UI_WIDGET_TONE_NEUTRAL || spec->tone > UI_WIDGET_TONE_ERROR ||
   763	        (spec->label_length > 0U && spec->label == NULL) ||
   764	        (spec->value_length > 0U && spec->value == NULL) ||
   765	        (spec->secondary_length > 0U && spec->secondary == NULL) ||
   766	        (spec->unit_length > 0U && spec->unit == NULL) ||
   767	        spec->segment_count > UI_WIDGET_MAX_SEGMENTS ||
   768	        (spec->kind == UI_WIDGET_SEGMENTED &&
   769	            spec->segment_count > UI_WIDGET_MAX_SEGMENTS)) return false;
   770	    if (spec->kind == UI_WIDGET_SEGMENTED) {
   771	        for (size_t index = 0U; index < spec->segment_count; ++index)
   772	            if (spec->segment_label_lengths[index] > UI_TEXT_TOTAL_MAX_BYTES ||
   773	                (spec->segment_label_lengths[index] > 0U &&
   774	                    spec->segment_labels[index] == NULL)) return false;
   775	    }
   776	    ui_widget_draw_spec adjusted = *spec;
   777	    if (adjusted.kind == UI_WIDGET_TOAST && adjusted.bounds.width > 360U)
   778	        adjusted.bounds.width = 360U;
   779	    bool result = paint_component(canvas, &adjusted);
   780	    ui_rect focus_bounds = adjusted.bounds;
   781	    if (adjusted.kind == UI_WIDGET_DROPDOWN && adjusted.expanded) focus_bounds.height = 30U;
   782	    if (result && (adjusted.focus_visible || adjusted.state == UI_CONTROL_FOCUS))
   783	        paint_focus(canvas, focus_bounds);
   784	    return result;
   785	}
